window.LM_TOOLS={"en": {"ui": {"stepOf": "Step {i} of {n}", "start": "Start", "next": "Next", "back": "Back", "pause": "Pause", "resume": "Resume", "stop": "Stop", "finish": "Finish", "finished": "Finished", "again": "Start again", "timeLeft": "left", "voiceGuide": "Voice guide", "ambLabel": "Background sound", "amb": {"off": "Off", "rain": "Soft rain", "hum": "Gentle tone"}, "noVoice": "This browser can't read aloud. You can still read the page on screen.", "noBmVoice": "Your phone has no Malay voice installed, so a similar voice is used.", "stopped": "Stopped", "tools": {"breathe": {"choose": "Choose a breathing pattern", "modes": {"calm": ["1-Minute Calm Breath", "in 4 · out 6"], "box": ["Box Breathing", "in 5 · hold 5 · out 6 · hold 5"]}, "ready": "Ready", "readyNote": "Sit comfortably. Choose 1 minute, or keep going for 2–5 minutes.", "start1": "Start (1 minute)", "keepGoing": "Keep going", "roundsOf": "Round {n} of {m}", "minutes": "{m}:{s}", "doneBox": "Three rounds done. Well done. Repeat if you like.", "voice": {"in": "Breathe in, gently", "out": "And breathe out, slowly", "hold": "Hold, softly"}, "words": {"in": "Breathe in", "out": "Breathe out", "hold": "Hold gently"}, "calmLeft": "{s} seconds left", "rounds": "Rounds completed: {n}", "doneWord": "Well done", "done": "One minute done. Notice how your body feels now.", "again": "Go again", "stopped": "Stopped. Breathe normally, at your own pace.", "care": "Breathe gently, never forcing. If you feel dizzy, short of breath or unsure, skip the holds and just breathe in and out slowly, or stop and breathe normally. If you have a heart or lung condition or are pregnant, ask your doctor or nurse before practising breath holds."}, "emotion": {"q1": "Which word is closest to how you feel right now?", "q2": "How strong is this feeling? (1 = mild, 10 = very strong)", "show": "Show me what might help", "strong": "**This is a strong feeling.** Calm your body first, then think. Try [1-minute breathing](#/tool/breathe) or [grounding](#/tool/ground) before making any decisions.", "tryNow": "Things you can try now", "unsafe": "If you feel unsafe or might hurt yourself, go to [Urgent Help](#/urgent) now."}}, "rxNote": "Your care team suggested this for you. Practise it at home, and tell them how it went at your next visit."}, "guides": {"ground": {"name": "5-4-3-2-1 Grounding", "time": "2–3 min", "intro": "This exercise brings your attention back to the here and now, using your five senses. Press Start, then Next after each step.", "care": "There is no wrong way to do this. Go at your own pace.", "steps": [["Look around. Name **5 things you can see**.", 0, "5"], ["Name **4 things you can touch**. Notice how they feel.", 0, "4"], ["Be still. Name **3 things you can hear**.", 0, "3"], ["Name **2 things you can smell**, or two smells you like.", 0, "2"], ["Name **1 thing you can taste**, or take a sip of water.", 0, "1"], ["Take one slow breath in, and a long breath out.", 8]], "done": "Done. Well done. Notice how you feel now."}, "pmr": {"name": "Muscle Relaxation", "time": "about 2 min", "intro": "Follow the voice. You will gently tense one part of your body, then let it go. Each step moves on by itself. Press Start when you are ready.", "care": "Tense gently, never to the point of pain. Skip any part that is sore or injured.", "steps": [["Sit or lie down comfortably. Close your eyes if you like.", 6], ["**Hands.** Make gentle fists, and hold.", 5], ["Let go. Notice the difference.", 10], ["**Shoulders.** Lift them gently towards your ears, and hold.", 5], ["Let go. Let them drop.", 10], ["**Face.** Scrunch up your face gently, and hold.", 5], ["Let go. Let your face go soft.", 10], ["**Stomach.** Tighten your stomach muscles, and hold.", 5], ["Let go. Breathe out slowly.", 10], ["**Legs.** Press your feet into the floor, and hold.", 5], ["Let go. Feel your legs grow heavy.", 10], ["Breathe slowly, and notice how your whole body feels.", 15]], "done": "Done. Well done. Take your time before you get up."}, "bodyscan": {"name": "Body Scan", "time": "about 5 min", "med": true, "intro": "Follow the voice. About 5 minutes. Also good before sleep. Press Start when ready.", "care": "If a part of your body is painful or injured, just notice it from a distance, or skip it. If upsetting memories come up, open your eyes and use [5-4-3-2-1](#/tool/ground).", "steps": [["Lie down or sit comfortably. Close your eyes if you like.", 12], ["Breathe in slowly, and breathe out long. Let your body feel heavy.", 15], ["Bring your attention to the soles of your feet. Notice whatever you feel. Warmth, coolness, or nothing at all.", 25], ["Move up to your ankles and calves. If there is tension, let it soften with each breath out.", 25], ["Now your knees and thighs. Feel the weight of your legs being supported.", 22], ["Your hips and lower back. Breathe out, and let them loosen.", 22], ["Your belly. Feel it rise and fall with your breath.", 22], ["Your chest and upper back. Nothing needs to change. Just notice.", 22], ["Your hands and fingers. Let your hands rest, heavy and soft.", 22], ["Your arms and shoulders. Let your shoulders drop, away from your ears.", 22], ["Your neck and jaw. Loosen your jaw. Let your teeth part a little.", 22], ["Your face. Forehead, eyes and cheeks. Let your face be calm.", 22], ["Now feel your whole body, from your toes to the top of your head, breathing calmly.", 30], ["Slowly, move your fingers and toes.", 12]], "done": "Done. Take your time before you get up."}, "medbreath": {"name": "Mindful Breathing", "time": "about 3 min", "med": true, "intro": "Follow the voice. About 3 minutes. You can open your eyes at any time. Press Start when ready.", "care": "If upsetting memories or confusing thoughts come up, open your eyes, stop, and use [5-4-3-2-1](#/tool/ground) instead.", "steps": [["Sit comfortably. Let your shoulders drop. Close your eyes, or rest your gaze softly on the floor.", 12], ["Breathe normally. There is nothing to change.", 12], ["Notice the air coming in through your nose, and going out again.", 15], ["Feel your chest or belly rise gently, and fall gently.", 18], ["Choose one place to rest your attention. The tip of your nose, your chest, or your belly.", 18], ["Your mind will wander. That is normal.", 12], ["When you notice your mind has wandered, gently bring your attention back to your breath.", 22], ["Breathe in. And breathe out.", 15], ["Each time you come back to the breath, that is the practice. You are doing well.", 22], ["Keep breathing calmly, at your own pace.", 25], ["Now, slowly, notice the sounds around you.", 10]], "done": "Done. Open your eyes slowly when you are ready."}, "medplace": {"name": "Calm Place", "time": "about 5 min", "med": true, "intro": "Follow the voice. About 5 minutes. Picture a place where you feel calm and safe. Press Start when ready.", "care": "If no place feels safe, imagine a made-up one. If upsetting memories come up, open your eyes, feel your feet on the floor, and use [5-4-3-2-1](#/tool/ground).", "steps": [["Sit or lie down comfortably. Close your eyes, or look softly downwards.", 12], ["Take a few slow breaths. Let each breath out be longer than the breath in.", 18], ["Picture a place where you feel calm and safe. It can be a real place, like a village, a riverside or a garden. Or a place you make up.", 30], ["Look around this place. What colours do you see? What is the light like?", 25], ["Listen. Perhaps water, wind, birds, or just quiet.", 25], ["Feel. Perhaps a cool breeze on your skin, the ground under your feet, or warm sunlight.", 25], ["Smell. Perhaps rain, flowers, or your favourite food.", 22], ["Here, there is nothing you need to do. You can rest.", 25], ["Feel your body becoming calmer, and lighter.", 25], ["If you like, give this place one word, like calm, or home. You can remember this word any time to come back here.", 30], ["Enjoy this place a little longer.", 25], ["Now, slowly come back to the room. Feel your feet on the floor.", 15]], "done": "Done. This place is always there for you. Open your eyes slowly."}, "medkind": {"name": "Kindness Meditation", "time": "about 4 min", "med": true, "intro": "Follow the voice. About 4 minutes. Sending good wishes to yourself and others. Press Start when ready.", "care": "You don't need to feel anything special. If it feels hard or sad, that is normal. You can use words or prayers from your own faith.", "steps": [["Sit comfortably. Place a hand on your chest if you like.", 12], ["Breathe slowly. Think of someone who is easy to love. Family, a friend, or a pet.", 22], ["In your heart, say to them. May you be safe. May you be well. May you be at peace.", 25], ["Notice what you feel. Maybe warmth, maybe nothing. Both are okay.", 20], ["Now, say to yourself. May I be safe. May I be well. May I be at peace.", 25], ["If this feels hard, that is normal. Just repeat it slowly.", 18], ["Think of someone you know a little, like a neighbour or a colleague. May you be safe, well, and at peace.", 25], ["Now, think of everyone in your home, your village, and everywhere. May everyone be safe, well, and at peace.", 28], ["Breathe calmly, and feel this kindness.", 25], ["Slowly, open your eyes when you are ready.", 10]], "done": "Done. Take a little of this kindness with you today."}, "sleepreset": {"name": "Sleep Reset", "time": "about 5 min", "intro": "Use this when you are lying awake and can't sleep. The aim is not to force sleep, but to help your body and mind settle. Press Start.", "care": "If you have been awake for more than about 20 minutes and feel frustrated, get up, go to another dim room, and do something quiet until you feel sleepy.", "steps": [["Put your phone face down, out of reach. Don't check the time again.", 0], ["Remind yourself: **resting quietly is still good for the body**. Sleep will come when it is ready.", 0], ["If a worry is going round your head, write it on paper and tell yourself: *I will deal with this tomorrow.*", 0], ["Breathe in gently for 4, and out slowly for 6.", 10], ["Again: in for 4, out for 6.", 10], ["Once more: in for 4, out for 6.", 10], ["Let your jaw loosen and your shoulders sink into the bed.", 12], ["Let your arms and legs feel heavy and warm.", 15], ["Picture a calm, familiar place, such as a riverside, a garden or your village. Notice the sounds and colours there.", 30], ["Stay with the picture and your slow breathing. There is nothing else you need to do.", 30]], "done": "Done. Stay resting. If you are still wide awake after a while, get up for a short time and come back to bed when you feel sleepy."}, "stressreset": {"name": "Stress Reset", "time": "about 3 min", "intro": "A short pause to calm your body and find one next step. Press Start.", "care": "", "steps": [["**Stop.** Whatever you are doing, pause for a moment.", 6], ["Feel your feet on the floor, and your body in the chair.", 10], ["Breathe out slowly, as if blowing out a candle. Do this three times.", 18], ["Let your shoulders drop, and unclench your hands and jaw.", 10], ["Name what is stressing you right now, in one sentence.", 0], ["Ask: **which part of this can I control?** Let go of the rest for now.", 0], ["Choose **one small next step** you can take in the next hour.", 0], ["Say something kind to yourself, such as: *I am doing my best. One step at a time.*", 8]], "done": "Done. Now take that one small step. For more ideas, see [Managing Stress](#/manage/stress)."}, "pause": {"name": "1-Minute Pause", "time": "about 1 min", "intro": "A very short reset you can do anywhere, even at work. Follow the voice. Press Start.", "care": "If upsetting memories or confusing thoughts come up, stop and use [5-4-3-2-1](#/tool/ground) instead.", "steps": [["Stop what you are doing.", 6], ["Feel your feet on the floor.", 12], ["Notice one sound you can hear.", 12], ["Notice one smell.", 10], ["Notice one thing you can see.", 10], ["Take one slow breath out.", 10]], "done": "Done. Carry on gently."}}}, "ms": {"ui": {"stepOf": "Langkah {i} daripada {n}", "start": "Mula", "next": "Seterusnya", "back": "Kembali", "pause": "Berhenti sekejap", "resume": "Sambung", "stop": "Berhenti", "finish": "Selesai", "finished": "Selesai", "again": "Cuba Lagi", "timeLeft": "lagi", "voiceGuide": "Panduan suara", "ambLabel": "Bunyi latar", "amb": {"off": "Tutup", "rain": "Hujan lembut", "hum": "Dengung lembut"}, "noVoice": "Pelayar ini tidak boleh membaca dengan suara. Anda masih boleh membaca halaman di skrin.", "noBmVoice": "Telefon anda tiada suara Bahasa Melayu, jadi suara yang hampir sama digunakan.", "stopped": "Dihentikan", "tools": {"breathe": {"choose": "Pilih corak pernafasan", "modes": {"calm": ["Pernafasan Tenang 1 Minit", "tarik 4 · hembus 6"], "box": ["Pernafasan Kotak", "tarik 5 · tahan 5 · hembus 6 · tahan 5"]}, "ready": "Sedia", "readyNote": "Duduk dengan selesa. Pilih 1 minit, atau teruskan selama 2–5 minit.", "start1": "Mula (1 minit)", "keepGoing": "Teruskan", "roundsOf": "Pusingan {n} daripada {m}", "minutes": "{m}:{s}", "doneBox": "Tiga pusingan selesai. Syabas. Ulang jika mahu.", "voice": {"in": "Tarik nafas, perlahan", "out": "Hembus, perlahan-lahan", "hold": "Tahan, dengan lembut"}, "words": {"in": "Tarik nafas", "out": "Hembus nafas", "hold": "Tahan perlahan"}, "calmLeft": "{s} saat lagi", "rounds": "Pusingan selesai: {n}", "doneWord": "Syabas", "done": "Satu minit selesai. Perhatikan bagaimana badan anda rasa sekarang.", "again": "Ulang lagi", "stopped": "Berhenti. Bernafas seperti biasa, ikut rentak anda sendiri.", "care": "Bernafas dengan lembut, jangan paksa. Jika anda rasa pening, sesak nafas atau tidak pasti, langkau bahagian menahan nafas dan bernafas masuk-keluar perlahan sahaja, atau berhenti dan bernafas seperti biasa. Jika anda mempunyai masalah jantung atau paru-paru atau sedang hamil, tanya doktor atau jururawat sebelum berlatih menahan nafas."}, "emotion": {"q1": "Perkataan manakah paling hampir dengan perasaan anda sekarang?", "q2": "Sekuat mana perasaan ini? (1 = sedikit, 10 = sangat kuat)", "show": "Tunjukkan apa yang mungkin membantu", "strong": "**Ini perasaan yang kuat.** Tenangkan badan dahulu, kemudian barulah berfikir. Cuba [pernafasan 1 minit](#/tool/breathe) atau [teknik grounding](#/tool/ground) sebelum membuat sebarang keputusan.", "tryNow": "Perkara yang boleh anda cuba sekarang", "unsafe": "Jika anda rasa tidak selamat atau mungkin mencederakan diri, pergi ke [Bantuan Segera](#/urgent) sekarang."}}, "rxNote": "Pasukan rawatan anda mencadangkan latihan ini. Amalkan di rumah, dan beritahu mereka bagaimana hasilnya pada temujanji seterusnya."}, "guides": {"ground": {"name": "Teknik Grounding 5-4-3-2-1", "time": "2–3 minit", "intro": "Latihan ini membawa perhatian anda kembali ke masa kini, menggunakan lima deria. Tekan Mula, kemudian Seterusnya selepas setiap langkah.", "care": "Tiada cara yang salah. Ikut rentak anda sendiri.", "steps": [["Lihat sekeliling. Namakan **5 benda yang anda nampak**.", 0, "5"], ["Namakan **4 benda yang boleh anda sentuh**. Perhatikan rasanya.", 0, "4"], ["Diam seketika. Namakan **3 bunyi yang anda dengar**.", 0, "3"], ["Namakan **2 bau yang anda hidu**, atau dua bau yang anda suka.", 0, "2"], ["Namakan **1 rasa yang anda kecap**, atau minum seteguk air.", 0, "1"], ["Tarik nafas perlahan, dan hembus panjang.", 8]], "done": "Selesai. Syabas. Perhatikan perasaan anda sekarang."}, "pmr": {"name": "Relaksasi Otot", "time": "kira-kira 2 minit", "intro": "Ikut suara. Anda akan menegangkan satu bahagian badan dengan perlahan, kemudian melepaskannya. Setiap langkah bergerak sendiri. Tekan Mula apabila sedia.", "care": "Tegangkan dengan perlahan, jangan sampai sakit. Langkau bahagian yang sakit atau cedera.", "steps": [["Duduk atau baring dengan selesa. Pejamkan mata jika mahu.", 6], ["**Tangan.** Genggam perlahan, dan tahan.", 5], ["Lepaskan. Rasakan perbezaannya.", 10], ["**Bahu.** Angkat perlahan ke arah telinga, dan tahan.", 5], ["Lepaskan. Biarkan bahu jatuh.", 10], ["**Muka.** Kerutkan muka perlahan, dan tahan.", 5], ["Lepaskan. Biarkan muka menjadi lembut.", 10], ["**Perut.** Ketatkan otot perut, dan tahan.", 5], ["Lepaskan. Hembus nafas perlahan.", 10], ["**Kaki.** Tekan tapak kaki ke lantai, dan tahan.", 5], ["Lepaskan. Rasakan kaki menjadi berat.", 10], ["Bernafas perlahan, dan perhatikan bagaimana seluruh badan anda rasa.", 15]], "done": "Selesai. Syabas. Ambil masa sebelum bangun."}, "bodyscan": {"name": "Imbasan Badan", "time": "kira-kira 5 minit", "med": true, "intro": "Ikut suara. Lebih kurang 5 minit. Sesuai juga sebelum tidur. Tekan Mula apabila sedia.", "care": "Jika ada bahagian yang sakit atau cedera, cukup perhatikan dari jauh, atau langkau. Jika ingatan yang menyedihkan muncul, buka mata dan guna [latihan 5-4-3-2-1](#/tool/ground).", "steps": [["Baring atau duduk dengan selesa. Pejamkan mata jika anda mahu.", 12], ["Tarik nafas perlahan, dan hembus panjang. Biarkan badan menjadi berat.", 15], ["Bawa perhatian ke tapak kaki. Perhatikan apa sahaja yang anda rasa. Hangat, sejuk, atau tiada rasa langsung.", 25], ["Naik ke buku lali dan betis. Jika ada rasa tegang, biarkan ia lembut dengan setiap hembusan.", 25], ["Sekarang lutut dan paha. Rasakan berat kaki anda disokong.", 22], ["Pinggul dan bahagian bawah belakang. Hembus, dan biarkan ia longgar.", 22], ["Perut. Rasakan perut naik dan turun bersama nafas.", 22], ["Dada dan bahagian atas belakang. Tiada apa yang perlu diubah. Hanya perhatikan.", 22], ["Tangan dan jari. Biarkan tangan berehat, berat dan lembut.", 22], ["Lengan dan bahu. Biarkan bahu jatuh, jauh dari telinga.", 22], ["Leher dan rahang. Longgarkan rahang. Biarkan gigi tidak rapat.", 22], ["Muka. Dahi, mata dan pipi. Biarkan muka menjadi tenang.", 22], ["Sekarang rasakan seluruh badan anda, dari hujung kaki hingga kepala, bernafas dengan tenang.", 30], ["Perlahan-lahan, gerakkan jari tangan dan jari kaki.", 12]], "done": "Selesai. Ambil masa sebelum anda bangun."}, "medbreath": {"name": "Nafas Berkesedaran", "time": "kira-kira 3 minit", "med": true, "intro": "Ikut suara. Lebih kurang 3 minit. Anda boleh buka mata bila-bila masa. Tekan Mula apabila sedia.", "care": "Jika ingatan yang menyedihkan atau fikiran yang mengelirukan muncul, buka mata, berhenti, dan guna [latihan 5-4-3-2-1](#/tool/ground).", "steps": [["Duduk dengan selesa. Biarkan bahu jatuh. Pejamkan mata, atau pandang lembut ke lantai.", 12], ["Bernafas seperti biasa. Tidak perlu mengubah apa-apa.", 12], ["Perhatikan udara masuk melalui hidung, dan keluar semula.", 15], ["Rasakan dada atau perut naik perlahan, dan turun perlahan.", 18], ["Pilih satu tempat untuk merehatkan perhatian. Hujung hidung, dada, atau perut.", 18], ["Fikiran akan melayang. Itu perkara biasa.", 12], ["Apabila anda sedar fikiran telah melayang, bawa perhatian kembali kepada nafas, dengan lembut.", 22], ["Tarik nafas. Dan hembus.", 15], ["Setiap kali anda kembali kepada nafas, itulah latihannya. Anda sedang melakukannya dengan baik.", 22], ["Terus bernafas dengan tenang, ikut rentak anda sendiri.", 25], ["Sekarang, perlahan-lahan, perhatikan bunyi di sekeliling anda.", 10]], "done": "Selesai. Buka mata perlahan-lahan apabila anda sedia."}, "medplace": {"name": "Tempat Yang Tenang", "time": "kira-kira 5 minit", "med": true, "intro": "Ikut suara. Lebih kurang 5 minit. Bayangkan satu tempat yang membuat anda rasa tenang dan selamat. Tekan Mula apabila sedia.", "care": "Jika tiada tempat yang terasa selamat, bayangkan tempat rekaan. Jika ingatan yang menyedihkan muncul, buka mata, rasakan kaki di lantai, dan guna [latihan 5-4-3-2-1](#/tool/ground).", "steps": [["Duduk atau baring dengan selesa. Pejamkan mata, atau pandang lembut ke bawah.", 12], ["Bernafas perlahan beberapa kali. Biarkan hembusan lebih panjang daripada tarikan.", 18], ["Bayangkan satu tempat di mana anda rasa tenang dan selamat. Ia boleh jadi tempat sebenar, seperti kampung, tepi sungai atau kebun. Atau tempat yang anda reka sendiri.", 30], ["Lihat sekeliling tempat itu. Apa warna yang anda nampak? Bagaimana cahayanya?", 25], ["Dengar. Mungkin bunyi air, angin, burung, atau hanya sunyi.", 25], ["Rasakan. Mungkin angin sejuk di kulit, tanah di bawah kaki, atau cahaya matahari yang hangat.", 25], ["Hidu. Mungkin bau hujan, bunga, atau makanan kegemaran anda.", 22], ["Di sini, tiada apa yang perlu anda buat. Anda boleh berehat.", 25], ["Rasakan badan anda menjadi lebih tenang, dan lebih ringan.", 25], ["Jika mahu, beri tempat ini satu perkataan, seperti tenang, atau rumah. Anda boleh ingat perkataan ini bila-bila masa untuk kembali ke sini.", 30], ["Nikmati tempat ini seketika lagi.", 25], ["Sekarang, perlahan-lahan kembali ke bilik ini. Rasakan kaki anda di lantai.", 15]], "done": "Selesai. Tempat ini sentiasa ada untuk anda. Buka mata perlahan-lahan."}, "medkind": {"name": "Kebaikan & Kasih Sayang", "time": "kira-kira 4 minit", "med": true, "intro": "Ikut suara. Lebih kurang 4 minit. Menghantar harapan yang baik kepada diri sendiri dan orang lain. Tekan Mula apabila sedia.", "care": "Tidak perlu rasa sesuatu yang istimewa. Jika terasa sukar atau sedih, itu biasa. Anda boleh guna kata-kata atau doa mengikut kepercayaan anda sendiri.", "steps": [["Duduk dengan selesa. Letakkan tangan di dada jika anda mahu.", 12], ["Bernafas perlahan. Fikirkan seseorang yang mudah anda sayangi. Keluarga, kawan, atau haiwan peliharaan.", 22], ["Dalam hati, ucapkan kepadanya. Semoga kamu selamat. Semoga kamu sihat. Semoga kamu tenang.", 25], ["Perhatikan apa yang anda rasa. Mungkin hangat, mungkin tiada apa-apa. Kedua-duanya tidak mengapa.", 20], ["Sekarang, ucapkan kepada diri sendiri. Semoga saya selamat. Semoga saya sihat. Semoga saya tenang.", 25], ["Jika terasa sukar, itu biasa. Cukup ulang dengan perlahan.", 18], ["Fikirkan seseorang yang anda kenal sedikit, seperti jiran atau rakan sekerja. Semoga kamu selamat, sihat, dan tenang.", 25], ["Kini, fikirkan semua orang di rumah anda, di kampung anda, dan di mana-mana sahaja. Semoga semua selamat, sihat, dan tenang.", 28], ["Bernafas dengan tenang, dan rasakan kebaikan ini.", 25], ["Perlahan-lahan, buka mata apabila anda sedia.", 10]], "done": "Selesai. Bawa sedikit kebaikan ini bersama anda hari ini."}, "sleepreset": {"name": "Tetapan Semula Tidur", "time": "kira-kira 5 minit", "intro": "Gunakan ini apabila anda terjaga dan tidak boleh tidur. Tujuannya bukan memaksa tidur, tetapi membantu badan dan minda menjadi tenang. Tekan Mula.", "care": "Jika sudah terjaga lebih kurang 20 minit dan rasa kecewa, bangun, pergi ke bilik lain yang malap, dan lakukan sesuatu yang tenang sehingga anda mengantuk.", "steps": [["Telangkupkan telefon dan letak jauh. Jangan lihat jam lagi.", 0], ["Ingatkan diri: **berehat dengan tenang tetap baik untuk badan**. Tidur akan datang apabila sudah tiba masanya.", 0], ["Jika ada kebimbangan berlegar dalam fikiran, tulis di atas kertas dan katakan: *Saya akan uruskan esok.*", 0], ["Tarik nafas perlahan kiraan 4, hembus perlahan kiraan 6.", 10], ["Sekali lagi: tarik 4, hembus 6.", 10], ["Sekali lagi: tarik 4, hembus 6.", 10], ["Longgarkan rahang dan biarkan bahu tenggelam ke tilam.", 12], ["Biarkan tangan dan kaki terasa berat dan hangat.", 15], ["Bayangkan tempat yang tenang dan biasa, seperti tepi sungai, kebun atau kampung anda. Perhatikan bunyi dan warna di sana.", 30], ["Kekal dengan gambaran itu dan pernafasan perlahan anda. Tiada apa lagi yang perlu dilakukan.", 30]], "done": "Selesai. Teruskan berehat. Jika masih segar selepas beberapa ketika, bangun sekejap dan kembali ke katil apabila mengantuk."}, "stressreset": {"name": "Tetapan Semula Tekanan", "time": "kira-kira 3 minit", "intro": "Rehat singkat untuk menenangkan badan dan mencari satu langkah seterusnya. Tekan Mula.", "care": "", "steps": [["**Berhenti.** Apa sahaja yang anda sedang lakukan, berhenti seketika.", 6], ["Rasakan tapak kaki di lantai, dan badan di kerusi.", 10], ["Hembus nafas perlahan, seperti meniup lilin. Lakukan tiga kali.", 18], ["Jatuhkan bahu, dan longgarkan genggaman tangan dan rahang.", 10], ["Namakan apa yang membuat anda tertekan sekarang, dalam satu ayat.", 0], ["Tanya: **bahagian mana yang boleh saya kawal?** Lepaskan yang selebihnya buat masa ini.", 0], ["Pilih **satu langkah kecil** yang boleh anda ambil dalam sejam ini.", 0], ["Katakan sesuatu yang baik kepada diri sendiri, seperti: *Saya sedang berusaha sebaik mungkin. Satu langkah pada satu masa.*", 8]], "done": "Selesai. Sekarang ambil satu langkah kecil itu. Untuk idea lain, lihat [Mengurus Tekanan](#/manage/stress)."}, "pause": {"name": "Rehat 1 Minit", "time": "kira-kira 1 minit", "intro": "Tetapan semula yang sangat singkat, boleh dibuat di mana-mana, walaupun di tempat kerja. Ikut suara. Tekan Mula.", "care": "Jika ingatan yang menyedihkan atau fikiran yang mengelirukan muncul, berhenti dan guna [latihan 5-4-3-2-1](#/tool/ground).", "steps": [["Berhenti daripada apa yang anda sedang buat.", 6], ["Rasakan kaki anda di lantai.", 12], ["Perhatikan satu bunyi yang anda dengar.", 12], ["Perhatikan satu bau.", 10], ["Perhatikan satu benda yang anda nampak.", 10], ["Hembus nafas perlahan sekali.", 10]], "done": "Selesai. Teruskan dengan tenang."}}}, "audio": {"en": {}, "ms": {}}, "routes": {"understand": "belajar.html", "understand/psychosis": "psikosis.html", "understand/mood": "kemurungan.html", "understand/anxiety": "kebimbangan.html", "understand/sleep": "tidur.html", "understand/substances": "bahan.html", "help/medicine": "ubat.html", "help/family": "keluarga.html", "help/appointment": "temu-janji.html", "help": "bantuan.html", "help/when": "bantuan.html", "help/talking": "bantuan.html", "help/resources": "bantuan.html", "help/services": "tentang.html", "about": "tentang.html", "about/minda-tenang": "tentang.html", "about/hospital": "tentang.html", "about/sources": "tentang.html", "about/disclaimer": "tentang.html", "urgent": "bantuan.html", "urgent/helplines": "bantuan.html", "urgent/emergency": "bantuan.html", "urgent/crisis": "bantuan.html", "manage": "kemahiran.html", "manage/breathing": "modul-pernafasan-perlahan.html", "tool/breathe": "modul-pernafasan-perlahan.html", "tool/box-breathing": "modul-pernafasan-perlahan.html", "tool/slow-breathing": "modul-pernafasan-perlahan.html", "manage/grounding": "grounding.html", "tool/ground": "grounding.html", "manage/relaxation": "relaksasi-otot.html", "tool/pmr": "relaksasi-otot.html", "tool/pause": "rehat-1-minit.html", "manage/sleep": "rutin-tidur.html", "tool/sleep-reset": "rutin-tidur.html#reset", "manage/emotions": "emosi-kuat.html", "tool/med-breath": "meditasi-nafas.html", "tool/med-body": "imbasan-badan.html", "tool/med-place": "tempat-tenang.html", "tool/med-kind": "meditasi-kasih.html", "manage/videos": "video.html", "manage/signs": "pelan-relaps.html", "manage/plan": "pelan-keselamatan.html"}};
